// ─── Fusion ───────────────────────────────────────────────────────────────────

const RECORDS_SUSPICIOUS = 3;      // one high-severity consistency check
const PROC_SUSPICIOUS = 3;         // e.g. a round-percentage bid plus thin competition

export type Quadrant = "both" | "records-only" | "procurement-only" | "neither";

export interface Fused {
  id: string;
  recordsScore: number;
  procurementScore: number;
  quadrant: Quadrant;
  budget: number;
}

/**
 * The 2x2 triage FUSION.md asks for, over every contract.
 *
 * Fusing is only worth doing if the two signals are independent, and they
 * measurably are: across all 1,293 contracts the records score and the
 * procurement score correlate at r = +0.05. Neither is a proxy for the other,
 * so "high on both" is genuinely narrower than either list alone.
 *
 * This is an ORDERING, not a prediction. There is no public itemised list of
 * confirmed ghost projects to validate against — the ICI turned its findings
 * over to the DOJ and Ombudsman rather than publishing them — so nothing here
 * has been shown to rank confirmed cases highly. It ranks contracts by how much
 * the public record disagrees with itself, which is a triage aid, not a verdict.
 */
export const FUSED: Fused[] = PROJECTS.map(p => {
  const proc = PROC_BY_ID.get(p.id);
  const ps = proc?.procurementScore ?? 0;
  const rs = p.auditScore;
  const hiR = rs >= RECORDS_SUSPICIOUS;
  const hiP = ps >= PROC_SUSPICIOUS;
  return {
    id: p.id,
    recordsScore: rs,
    procurementScore: ps,
    budget: p.budget,
    quadrant: (hiR && hiP ? "both" : hiR ? "records-only"
      : hiP ? "procurement-only" : "neither") as Quadrant,
  };
});

export const FUSED_BY_ID = new Map(FUSED.map(f => [f.id, f]));

export const QUADRANT_CFG: Record<Quadrant, { label: string; short: string; color: string; bg: string; note: string }> = {
  "both": {
    label: "Records and procurement both flag it", short: "Both",
    color: "#b91c1c", bg: "#fee2e2",
    note: "The contract record disagrees with itself AND the bidding shows a red flag — a whole-percentage bid, thin competition, or a heavily concentrated contractor. Two independent signals, so this is where inspection effort goes first.",
  },
  "records-only": {
    label: "Contract record only", short: "Records",
    color: "#b45309", bg: "#fef3c7",
    note: "The published record is internally inconsistent, but nothing stands out on the procurement side.",
  },
  "procurement-only": {
    label: "Procurement only", short: "Procurement",
    color: "#0369a1", bg: "#e0f2fe",
    note: "The bidding shows a red flag, but the contract record itself is consistent.",
  },
  "neither": {
    label: "Neither signal", short: "Neither",
    color: "#64748b", bg: "#f1f5f9",
    note: "Nothing flagged. Given how much the public record omits, this means 'nothing visible here', not 'clean'.",
  },
};

export const TRIAGE = (() => {
  const counts: Record<Quadrant, number> = { both: 0, "records-only": 0, "procurement-only": 0, neither: 0 };
  const value: Record<Quadrant, number> = { both: 0, "records-only": 0, "procurement-only": 0, neither: 0 };
  for (const f of FUSED) { counts[f.quadrant]++; value[f.quadrant] += f.budget; }
  return { counts, value };
})();

/** The "investigate first" list: both signals, highest value first. */
export const PRIORITY = FUSED
  .filter(f => f.quadrant === "both")
  .sort((a, b) => b.budget - a.budget);


// ─── Flood hazard ─────────────────────────────────────────────────────────────
// UP NOAH 100-year modelled flood extent, joined by point-in-polygon. For a
// flood-control register this asks the question the money is meant to answer.
//
// Read it with the distance, not without: 306 contracts sit outside the modelled
// extent but within a kilometre of it, which is where you build a revetment. Only
// 3 are further out — and all three already carry a coordinate flag, so this
// corroborates the records tier rather than finding anything new.

export interface HazardResult {
  id: string;
  hazard: "none" | "low" | "medium" | "high" | null;
  level: number | null;
  metresToHazard: number | null;
}
export interface HazardRun {
  generated: string;
  source: { name: string; dataset: string; file: string; url: string; crs: string; polygonParts: number };
  caveat: string;
  farThresholdMetres: number;
  tally: Record<string, number>;
  results: HazardResult[];
}
export const HAZARD = hazardRaw as unknown as HazardRun;
export const HAZARD_BY_ID = new Map(HAZARD.results.map(r => [r.id, r]));

/**
 * Year-by-year comparison.
 *
 * BetterGov's flood-control map (CC0, bettergovph/bettergov) has a "Projects by
 * Year" chart, and it is the right idea — this adopts it and adds the columns
 * their data cannot produce, because they plot the register rather than audit it.
 *
 * The reason it is worth showing: the round-number bidding pattern has a start
 * date. It is absent through 2018, appears at 3% in 2019, and jumps to 51% in
 * 2020 — where it stays. A yearly view is the only place that shows up.
 *
 * Reported as TWO series on two charts rather than one chart with two axes.
 * Value and percentage do not share a scale, and a dual-axis chart can be made
 * to show any relationship the author wants.
 */
export interface YearStat {
  year: number;
  projects: number;
  value: number;
  valueM: number;
  flagged: number;
  flaggedRate: number;
  at96: number;
  at96Rate: number;
  singleBidder: number;
  withRatio: number;
}

export const YEAR_STATS: YearStat[] = (() => {
  const years = [...new Set(PROJECTS.map(p => p.infraYear).filter((y): y is number => y != null))].sort();
  return years.map(year => {
    const g = PROJECTS.filter(p => p.infraYear === year);
    const ratios = g.map(p => PROC_BY_ID.get(p.id)?.bidRatio).filter((r): r is number => r != null);
    const at96 = ratios.filter(r => Math.abs(r * 100 - 96) < 0.01).length;
    const flagged = g.filter(p => p.auditFlags.length > 0).length;
    const value = g.reduce((s, p) => s + p.budget, 0);
    return {
      year, projects: g.length, value, valueM: Math.round(value / 1e6),
      flagged, flaggedRate: g.length ? flagged / g.length : 0,
      at96, at96Rate: ratios.length ? at96 / ratios.length : 0,
      singleBidder: g.filter(p => PROC_BY_ID.get(p.id)?.bidders === 1).length,
      withRatio: ratios.length,
    };
  });
})();
